// Compact four source keys locally, then scatter one subtotal per group.
// This changes only the exact combinational bucket-delta histogram.
private val hitBounds = Seq(8 min lineBytes, 3 min word4Count,
  2 min word8Count, 1)
private def bucketHistogram(keys: Seq[UInt], counts: Seq[Seq[UInt]],
  bounds: Seq[Int], slots: Int): Vec[Vec[UInt]] = {
  if (keys.size % 4 == 0) AddressBucketGrouped.histogram(keys, counts, bounds, slots)
  else VecInit((0 until slots).map(i => VecInit(bounds.indices.map(g =>
    exactHitSum(keys.indices.map(j => Mux(keys(j) === i.U,
      counts(j)(g).pad(64), 0.U(64.W))), bounds(g))))))
}

// Multi-bucket hits still update in parallel. Reuse each exact 65-bit sum
// for its carry check and its low-64-bit counter update.
val loadFirstNextWide = Wire(Vec(packetWindow, Vec(4, UInt(65.W))))
val storeFirstNextWide = Wire(Vec(packetWindow, Vec(4, UInt(65.W))))
val strictWriteReadNextWide = Wire(Vec(packetWindow, Vec(4, UInt(65.W))))
for (i <- 0 until packetWindow; g <- 0 until 4) {
  loadFirstNextWide(i)(g) := bucketLoadFirst(i)(g) +& bucketLoadFirstDelta(i)(g)
  storeFirstNextWide(i)(g) := bucketStoreFirst(i)(g) +& bucketStoreFirstDelta(i)(g)
  strictWriteReadNextWide(i)(g) := bucketStrictWriteRead(i)(g) +& bucketStrictWriteReadDelta(i)(g)
}
// Exactly one current bucket receives these two kinds of increments.
// Read/mux once and share four adders instead of 256 copies of each.
val currentStoreNextWide = Wire(Vec(4, UInt(65.W)))
val currentFirstStoreNextWide = Wire(Vec(4, UInt(65.W)))
for (g <- 0 until 4) {
  currentStoreNextWide(g) := Mux(bucketValid(currentBucketIdx),
    bucketStore(currentBucketIdx)(g), 0.U(64.W)) +& newStoreCounts(g).pad(64)
  currentFirstStoreNextWide(g) := Mux(bucketValid(currentBucketIdx),
    bucketFirstStore(currentBucketIdx)(g), 0.U(64.W)) +& newFirstStoreCounts(g).pad(64)
}

for (i <- 0 until packetWindow) {
  val isCurrent = currentBucketIdx === i.U
  when (isCurrent) {
    bucketValid(i) := true.B
    bucketSeq(i) := processEvent.packetSeq
  }
  for (g <- 0 until 4) {
    when (isCurrent) {
      bucketStore(i)(g) := currentStoreNextWide(g)(63, 0)
      bucketFirstStore(i)(g) := currentFirstStoreNextWide(g)(63, 0)
    }
    // Preserve allocation from zero even after an independent global
    // reset leaves an arbitrary payload in an invalid slot. All counter
    // values and all input cycles retain the original behavior.
    val allocate = isCurrent && !bucketValid(i)
    when (AddressBucketUpdate.enabled(isCurrent, bucketLoadFirstDelta(i)(g))) {
      bucketLoadFirst(i)(g) := Mux(allocate, bucketLoadFirstDelta(i)(g),
        loadFirstNextWide(i)(g)(63, 0))
    }
    when (AddressBucketUpdate.enabled(isCurrent, bucketStoreFirstDelta(i)(g))) {
      bucketStoreFirst(i)(g) := Mux(allocate, bucketStoreFirstDelta(i)(g),
        storeFirstNextWide(i)(g)(63, 0))
    }
    when (AddressBucketUpdate.enabled(isCurrent, bucketStrictWriteReadDelta(i)(g))) {
      bucketStrictWriteRead(i)(g) := Mux(allocate, bucketStrictWriteReadDelta(i)(g),
        strictWriteReadNextWide(i)(g)(63, 0))
    }
  }
}

for (i <- 0 until packetWindow) {
  bucketValid(i) := false.B
  bucketSeq(i) := 0.U
  for (g <- 0 until 4) {
    bucketStore(i)(g) := 0.U
    bucketFirstStore(i)(g) := 0.U
    bucketLoadFirst(i)(g) := 0.U
    bucketStoreFirst(i)(g) := 0.U
    bucketStrictWriteRead(i)(g) := 0.U
  }
}

